#include <iostream>

template<typename T>
class MyContainer {
public:
    void display() { std::cout << "Generic template" << std::endl; }
};

// Full specialization for int
template<>
class MyContainer<int> {
public:
    void display() { std::cout << "Specialized template for int" << std::endl; }
};

int main() {
    MyContainer<double> c1;
    c1.display(); // Outputs: Generic template
    MyContainer<int> c2;
    c2.display(); // Outputs: Specialized template for int
    return 0;
}
